/**
 * Demo corpus.
 *
 * These profiles are written directly rather than generated by running real
 * interviews, so `npm run db:seed` works with no API key and costs nothing. The
 * shape matches exactly what the finish route produces, so manager search and the
 * candidate report render the same way they will with real data.
 *
 * Every person here is invented.
 */

import { PrismaClient } from "@prisma/client";
import { embed } from "../src/lib/embeddings";

const db = new PrismaClient();

type Seed = {
  name: string;
  email: string;
  location: string;
  headline: string;
  sector: string;
  seniority: string;
  roleTitle: string;
  years: number;
  score: number;
  recommendation: string;
  summary: string;
  competencies: { competencyId: string; label: string; score: number; confidence: "low" | "medium" | "high"; evidence: string; note: string }[];
  strengths: string[];
  concerns: string[];
  tags: { label: string; kind: string; confidence: number; status: string; evidence: string }[];
};

