async function main() {
  console.log("Seeding demo candidates…");

  for (const s of SEEDS) {
    const candidate = await db.candidate.upsert({
      where: { email: s.email },
      create: {
        email: s.email,
        name: s.name,
        location: s.location,
        consentInterview: true,
        consentRecording: true,
        consentLinkCheck: false,
        consentedAt: new Date(),
        consentPolicyVer: "2026-08-23",
      },
      update: { name: s.name, location: s.location },
    });

    const searchText = [
      s.headline,
      `${s.seniority} ${s.roleTitle}`,
      s.sector,
      s.summary,
      s.tags.flatMap((t) => (t.status === "demonstrated" ? [t.label, t.label] : [t.label])).join(" "),
      s.competencies.map((c) => `${c.label} ${c.note}`).join(" "),
    ].join("\n");

    const embedding = await embed(searchText);

    await db.candidateProfile.upsert({
      where: { candidateId: candidate.id },
      create: {
        candidateId: candidate.id,
        headline: s.headline,
        sector: s.sector,
        seniority: s.seniority,
        yearsExperience: s.years,
        overallScore: s.score,
        recommendation: s.recommendation,
        summary: s.summary,
        searchText,
        embedding: JSON.stringify(embedding),
        competencies: JSON.stringify(s.competencies),
      },
      update: {
        headline: s.headline,
        overallScore: s.score,
        summary: s.summary,
        searchText,
        embedding: JSON.stringify(embedding),
        competencies: JSON.stringify(s.competencies),
      },
    });

    for (const t of s.tags) {
      const tag = await db.tag.upsert({
        where: { label: t.label },
        create: { label: t.label, kind: t.kind },
        update: {},
      });
      await db.candidateTag.upsert({
        where: { candidateId_tagId: { candidateId: candidate.id, tagId: tag.id } },
        create: {
          candidateId: candidate.id,
          tagId: tag.id,
          confidence: t.confidence,
          status: t.status,
          evidence: t.evidence || null,
        },
        update: { confidence: t.confidence, status: t.status },
      });
    }

    // A completed interview + assessment so the candidate report page renders.
    const resume = await db.resume.create({
      data: {
        candidateId: candidate.id,
        filename: "seed.txt",
        mimeType: "text/plain",
        rawText: `${s.name}\n${s.headline}\n(seed data)`,
        extracted: JSON.stringify({
          name: s.name, headline: s.headline, totalYearsExperience: s.years,
          employment: [], education: [], skills: [], notableClaims: [], links: [],
          email: s.email, phone: "", location: s.location, summary: s.summary,
          sector: s.sector, seniority: s.seniority, gapsOrOddities: [],
        }),
      },
    });

    const interview = await db.interview.create({
      data: {
        candidateId: candidate.id,
        resumeId: resume.id,
        sector: s.sector,
        roleTitle: s.roleTitle,
        seniority: s.seniority,
        status: "completed",
        completedAt: new Date(),
        plan: JSON.stringify({ questionBudget: 12, targets: [], resumeProbes: [] }),
      },
    });

    await db.assessment.create({
      data: {
        interviewId: interview.id,
        overallScore: s.score,
        recommendation: s.recommendation,
        summary: s.summary,
        competencies: JSON.stringify(s.competencies),
        strengths: JSON.stringify(s.strengths),
        concerns: JSON.stringify(s.concerns),
        integrity: JSON.stringify({
          anomalyScore: 0,
          band: "nothing_notable",
          observations: [],
          counts: {},
          caveat:
            "These are behavioural observations, not proof. Seed data — no real session was monitored.",
        }),
        resumeDeltas: JSON.stringify([]),
      },
    });

    console.log(`  ${s.name} — ${s.score}/100`);
  }

  console.log(`\nDone. ${SEEDS.length} candidates seeded.`);
  console.log('Try the manager search with: "Software engineer who has experience with PyTorch"');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => db.$disconnect());
